-- Six more SAMPLE partners for "Our Partners" (twelve in all), with their
-- placeholder logos (400 x 400 px PNG), each added after the partners already
-- listed. Ordinary partners from here on: edit, reorder, hide or delete them
-- under Website -> Our Partners. The names are fictional.

INSERT INTO "Partner" ("id", "name", "website", "logoData", "logoType", "logoUpdatedAt", "published", "sortOrder", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'Kaveri Steel Works', NULL, decode('', 'hex'), 'image/png', CURRENT_TIMESTAMP, true,
       LEAST(COALESCE((SELECT MAX("sortOrder") FROM "Partner"), -10) + 10, 9999), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "Partner" WHERE "name" = 'Kaveri Steel Works');

